    user: TAccountMetas[3];
    /** Owned Token Account Of Mint */
    ownerTokenAccount: TAccountMetas[4];
    /** Metadata account */
    metadata: TAccountMetas[5];
    /** Mint of Metadata */
    mint: TAccountMetas[6];
    /** Program As Signer (Burner) */
    burner: TAccountMetas[7];
    /** Token program */
    tokenProgram: TAccountMetas[8];
